/// `toJSON()` (`[Default]`: Web IDL's default toJSON steps over the attributes of the
/// inheritance stack).
fn op_to_json_default<D: Dom, const LO: u16, const HI: u16>(
    scope: &mut v8::PinScope,
    args: v8::FunctionCallbackArguments,
    mut rv: v8::ReturnValue,
) {
    let _prof = rt::prof::enter(scope, "Performance.toJSON");
    if rt::unwrap(&args.this(), LO, HI).is_none() {
        return rt::throw_illegal_invocation(scope);
    }
    let Some(o) = rt::default_to_json(
        scope,
        args.this(),
        &["timeOrigin", "interactionCount", "timing", "navigation"],
    ) else {
        return;
    };
    rv.set(o.into());
}

